# Manual pagination and deduplication without helpers
access_token = apis.spotify.access_token_from(main_user)
artist_ids = set()
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=access_token, page_index=page_index)
    if not page.playlists:
        break
    for playlist in page.playlists:
        pl = apis.spotify.show_playlist(playlist_id=playlist.playlist_id, access_token=access_token)
        for song in pl.songs:
            s = apis.spotify.show_song(song_id=song.id)
            if s.genre == target_genre:
                for artist in s.artists:
                    artist_ids.add(artist.id)
    page_index += 1

for artist_id in artist_ids:
    result = apis.spotify.follow_artist(access_token=access_token, artist_id=artist_id, raise_on_failure=False)
    # Continue even if result indicates an error/already followed

apis.supervisor.complete_task(status="success")
